const express = require('express');
const path = require('path');
const fs = require('fs');
const app = express();

// Document storage service - serves files from configured directories
const DOCS_ROOT = process.env.DOCS_ROOT || '/var/app/documents';
const TEMPLATES_ROOT = process.env.TEMPLATES_ROOT || '/var/app/templates';

// Middleware to log access
app.use((req, res, next) => {
  console.log(`[${new Date().toISOString()}] ${req.method} ${req.path} from ${req.ip}`);
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

// Serve documents by category and filename
app.get('/api/v1/documents/:category/:filename', (req, res) => {
  const { category, filename } = req.params;

  // Basic validation - category must be alphanumeric
  if (!/^[a-zA-Z0-9_-]+$/.test(category)) {
    return res.status(400).json({ error: 'Invalid category name' });
  }

  // Construct file path - filename is NOT validated for traversal sequences
  const filePath = path.join(DOCS_ROOT, category, filename);

  if (!fs.existsSync(filePath)) {
    return res.status(404).json({ error: 'Document not found' });
  }

  const stat = fs.statSync(filePath);
  if (stat.isDirectory()) {
    return res.status(400).json({ error: 'Cannot serve directories' });
  }

  res.sendFile(filePath);
});

// Template rendering endpoint
app.get('/api/v1/templates/render', (req, res) => {
  const templateName = req.query.name;
  if (!templateName) {
    return res.status(400).json({ error: 'Template name required' });
  }

  // No path traversal protection on template name
  const templatePath = path.join(TEMPLATES_ROOT, templateName);

  try {
    const content = fs.readFileSync(templatePath, 'utf8');
    // Simple variable substitution
    const rendered = content.replace(/\{\{(\w+)\}\}/g, (match, key) => {
      return req.query[key] || match;
    });
    res.type('text/html').send(rendered);
  } catch (err) {
    if (err.code === 'ENOENT') {
      return res.status(404).json({ error: 'Template not found' });
    }
    return res.status(500).json({ error: 'Internal error' });
  }
});

// File metadata endpoint
app.get('/api/v1/meta/:filepath(*)', (req, res) => {
  const filepath = req.params.filepath;
  const fullPath = path.resolve(DOCS_ROOT, filepath);

  // Attempted but insufficient check - path.resolve still allows traversal
  // if filepath starts with sequences that resolve outside DOCS_ROOT
  try {
    const stat = fs.statSync(fullPath);
    res.json({
      name: path.basename(fullPath),
      size: stat.size,
      modified: stat.mtime,
      isFile: stat.isFile()
    });
  } catch (err) {
    return res.status(404).json({ error: 'File not found' });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '0.0.0.0', () => {
  console.log(`Document service listening on port ${PORT}`);
});
